ps.pstext:
if !IsFeatureImplemented(FEAT_AA32EL1) then
    Undefined();
elsif HaveEL(EL3) && PSTATE.EL IN {EL1, EL2} && EL3SDDUndefPriority() && IsFeatureImplemented(FEAT_AA64EL3) && !ELUsingAArch32(EL3) && CPTR_EL3().TFP == '1' then
    Undefined();
elsif PSTATE.EL == EL0 then
    Undefined();
elsif PSTATE.EL == EL1 then
    if (IsFeatureImplemented(FEAT_AA32EL3) && ELUsingAArch32(EL3) && SCR().NS == '1' && NSACR().cp10 == '0') || CPACR().cp10 == '00' then
        Undefined();
    elsif EL2Enabled() && IsFeatureImplemented(FEAT_AA64EL2) && !ELUsingAArch32(EL2) && !ELIsInHost(EL2) && CPTR_EL2().TFP == '1' then
        AArch64_AArch32SystemAccessTrap(EL2, 0x07);
    elsif ELIsInHost(EL2) && IsFeatureImplemented(FEAT_AA64EL2) && !ELUsingAArch32(EL2) && CPTR_EL2().FPEN IN {'x0'} then
        AArch64_AArch32SystemAccessTrap(EL2, 0x07);
    elsif EL2Enabled() && IsFeatureImplemented(FEAT_AA32EL2) && ELUsingAArch32(EL2) && ((IsFeatureImplemented(FEAT_AA32EL3) && ELUsingAArch32(EL3) && SCR().NS == '1' && NSACR().cp10 == '0') || HCPTR().TCP10 == '1') then
        AArch32_TakeHypTrapException(0x08);
    elsif EL2Enabled() && IsFeatureImplemented(FEAT_AA64EL2) && !ELUsingAArch32(EL2) && HCR_EL2().TID3 == '1' then
        AArch64_AArch32SystemAccessTrap(EL2, 0x08);
    elsif EL2Enabled() && IsFeatureImplemented(FEAT_AA32EL2) && ELUsingAArch32(EL2) && HCR().TID3 == '1' then
        AArch32_TakeHypTrapException(0x08);
    elsif HaveEL(EL3) && IsFeatureImplemented(FEAT_AA64EL3) && !ELUsingAArch32(EL3) && CPTR_EL3().TFP == '1' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_AArch32SystemAccessTrap(EL3, 0x07);
        end;
    else
        R(t) = MVFR2();
    end;
elsif PSTATE.EL == EL2 then
    if EL2Enabled() && ((IsFeatureImplemented(FEAT_AA32EL3) && ELUsingAArch32(EL3) && SCR().NS == '1' && NSACR().cp10 == '0') || HCPTR().TCP10 == '1') then
        AArch32_TakeHypTrapException(0x00);
    elsif HaveEL(EL3) && IsFeatureImplemented(FEAT_AA64EL3) && !ELUsingAArch32(EL3) && CPTR_EL3().TFP == '1' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_AArch32SystemAccessTrap(EL3, 0x07);
        end;
    else
        R(t) = MVFR2();
    end;
elsif PSTATE.EL == EL3 then
    if CPACR().cp10 == '00' then
        Undefined();
    else
        R(t) = MVFR2();
    end;
end;
